package org.namewta.common.openapi.protocol;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.Base64;

/**
 * HMAC-SHA256 signing and verification for NAMEWTA v1.
 */
public final class OpenApiSigner {

    private final OpenApiCanonicalizer canonicalizer;

    public OpenApiSigner(OpenApiCanonicalizer canonicalizer) {
        this.canonicalizer = canonicalizer;
    }

    public String sign(OpenApiRequest request, String appSecret) {
        byte[] key = decodeSecret(appSecret);
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            byte[] signature = mac.doFinal(canonicalizer.canonicalize(request).getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(signature);
        } catch (GeneralSecurityException exception) {
            throw new IllegalStateException("HMAC-SHA256 is not available", exception);
        } finally {
            java.util.Arrays.fill(key, (byte) 0);
        }
    }

    public boolean verify(OpenApiRequest request, String appSecret, String suppliedSignature) {
        try {
            byte[] expected = Base64.getUrlDecoder().decode(sign(request, appSecret));
            byte[] actual = Base64.getUrlDecoder().decode(suppliedSignature);
            return MessageDigest.isEqual(expected, actual);
        } catch (IllegalArgumentException exception) {
            return false;
        }
    }

    private static byte[] decodeSecret(String appSecret) {
        try {
            byte[] key = Base64.getUrlDecoder().decode(appSecret);
            if (key.length < 32) {
                throw new OpenApiAuthenticationException();
            }
            return key;
        } catch (IllegalArgumentException exception) {
            throw new OpenApiAuthenticationException(exception);
        }
    }

}

package org.namewta.common.openapi.ratelimit;

import java.time.Duration;

/**
 * Atomic distributed rate limiter for one opaque OpenAPI scope.
 */
@FunctionalInterface
public interface OpenApiRateLimiter {

    boolean acquire(String scope, int limit, Duration interval);

}

package org.namewta.common.openapi.ratelimit;

import org.namewta.common.openapi.gateway.OpenApiStateStoreException;
import org.redisson.api.RRateLimiter;
import org.redisson.api.RateType;
import org.redisson.api.RedissonClient;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Duration;
import java.util.HexFormat;
import java.util.Objects;

/**
 * Redisson-backed atomic limiter with scope material hashed out of Redis key names.
 */
public final class RedissonOpenApiRateLimiter implements OpenApiRateLimiter {

    private static final String KEY_PREFIX = "openapi:rate:";

    private final RedissonClient redissonClient;

    public RedissonOpenApiRateLimiter(RedissonClient redissonClient) {
        this.redissonClient = Objects.requireNonNull(redissonClient, "redissonClient");
    }

    @Override
    public boolean acquire(String scope, int limit, Duration interval) {
        Objects.requireNonNull(scope, "scope");
        requirePositive(limit, interval);
        try {
            RRateLimiter limiter = redissonClient.getRateLimiter(key(scope, limit, interval));
            limiter.trySetRate(RateType.OVERALL, limit, interval);
            return limiter.tryAcquire();
        } catch (RuntimeException exception) {
            throw new OpenApiStateStoreException(exception);
        }
    }

    private static String key(String scope, int limit, Duration interval) {
        try {
            String versionedScope = scope + '\n' + limit + '\n' + interval.toMillis();
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(versionedScope.getBytes(StandardCharsets.UTF_8));
            return KEY_PREFIX + HexFormat.of().formatHex(digest);
        } catch (Exception exception) {
            throw new IllegalStateException("SHA-256 unavailable", exception);
        }
    }

    private static void requirePositive(int limit, Duration interval) {
        Objects.requireNonNull(interval, "interval");
        if (limit <= 0 || interval.isZero() || interval.isNegative()) {
            throw new IllegalArgumentException("rate limit and interval must be positive");
        }
    }
}

