/**
 * 基于请求头解析国际化区域信息的语言解析器。
 *
 * @author Lion Li
 */
public class I18nLocaleResolver implements LocaleResolver {

    /**
     * 从请求头 {@code content-language} 中解析本次请求的区域信息，缺省时回退到系统默认区域。
     *
     * @param httpServletRequest 当前请求
     * @return 当前请求对应的区域设置
     */
    @Override
    public Locale resolveLocale(HttpServletRequest httpServletRequest) {
        String language = httpServletRequest.getHeader("content-language");
        Locale locale = Locale.getDefault();
        if (language != null && !language.isEmpty()) {
            locale = Locale.forLanguageTag(language.replace('_', '-'));
        }
        return locale;
    }

    /**
     * 当前项目不在服务端主动切换区域信息，因此保留空实现。
     *
     * @param httpServletRequest  当前请求
     * @param httpServletResponse 当前响应
     * @param locale              目标区域
     */
    @Override
    public void setLocale(HttpServletRequest httpServletRequest, HttpServletResponse httpServletResponse, Locale locale) {

    }
}

package org.namewta.common.web.core;

import cn.hutool.captcha.AbstractCaptcha;
import cn.hutool.captcha.generator.CodeGenerator;
import cn.hutool.captcha.generator.RandomGenerator;
import cn.hutool.core.img.GraphicsUtil;
import cn.hutool.core.img.ImgUtil;
import cn.hutool.core.util.ObjectUtil;
import cn.hutool.core.util.RandomUtil;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.Serial;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 带干扰线、波浪和圆形干扰元素的验证码实现，用于增强验证码识别难度。
 *
 * @author Lion Li
 */
public class WaveAndCircleCaptcha extends AbstractCaptcha {

    @Serial
    private static final long serialVersionUID = 1L;

    /**
     * 构造默认长度为 4 的验证码。
     *
     * @param width  图片宽度
     * @param height 图片高度
     */
    public WaveAndCircleCaptcha(int width, int height) {
        this(width, height, 4);
    }

    /**
     * 构造指定验证码长度的验证码对象。
     *
     * @param width     图片宽度
     * @param height    图片高度
     * @param codeCount 验证码字符数
     */
    public WaveAndCircleCaptcha(int width, int height, int codeCount) {
        this(width, height, codeCount, 6);
    }

    /**
     * 构造指定字符数与干扰数的验证码对象。
     *
     * @param width          图片宽度
     * @param height         图片高度
     * @param codeCount      验证码字符数
     * @param interfereCount 干扰元素数量
     */
    public WaveAndCircleCaptcha(int width, int height, int codeCount, int interfereCount) {
        this(width, height, new RandomGenerator(codeCount), interfereCount);
    }

    /**
     * 使用指定验证码生成器构造验证码对象。
     *
     * @param width          图片宽度
     * @param height         图片高度
     * @param generator      验证码生成器
     * @param interfereCount 干扰元素数量
     */
    public WaveAndCircleCaptcha(int width, int height, CodeGenerator generator, int interfereCount) {
        super(width, height, generator, interfereCount);
    }

    /**
     * 构造带字体缩放比例的验证码对象。
     *
     * @param width          图片宽度
     * @param height         图片高度
     * @param codeCount      验证码字符数
     * @param interfereCount 干扰元素数量
     * @param size           字体相对尺寸
     */
    public WaveAndCircleCaptcha(int width, int height, int codeCount, int interfereCount, float size) {
        super(width, height, new RandomGenerator(codeCount), interfereCount, size);
    }

    /**
     * 生成验证码图片并绘制文字、扭曲效果及干扰图形。
     *
     * @param code 验证码文本
     * @return 生成后的验证码图片
     */
    @Override
    public Image createImage(String code) {
        final BufferedImage image = new BufferedImage(
            width,
            height,
            (null == this.background) ? BufferedImage.TYPE_4BYTE_ABGR : BufferedImage.TYPE_INT_RGB
        );
        final Graphics2D g = ImgUtil.createGraphics(image, this.background);

        try {
            drawString(g, code);
            // 扭曲
            shear(g, this.width, this.height, ObjectUtil.defaultIfNull(this.background, Color.WHITE));
            drawInterfere(g);
        } finally {
            g.dispose();
        }

        return image;
    }

    /**
     * 绘制验证码文本并开启文字抗锯齿。
     *
     * @param g    图形上下文
     * @param code 验证码文本
     */
    private void drawString(Graphics2D g, String code) {
        // 设置抗锯齿（让字体渲染更清晰）
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        if (this.textAlpha != null) {
            g.setComposite(this.textAlpha);
        }

        GraphicsUtil.drawStringColourful(g, code, this.font, this.width, this.height);
    }

    /**
     * 绘制圆形与波浪线干扰元素。
     *
     * @param g 图形上下文
     */
    protected void drawInterfere(Graphics2D g) {
        ThreadLocalRandom random = RandomUtil.getRandom();
        int circleCount = Math.max(0, this.interfereCount - 1);

        // 圈圈
        for (int i = 0; i < circleCount; i++) {
            g.setColor(ImgUtil.randomColor(random));
            int x = random.nextInt(width);
            int y = random.nextInt(height);
            int w = random.nextInt(height >> 1);
            int h = random.nextInt(height >> 1);
            g.drawOval(x, y, w, h);
        }

        // 仅 1 条平滑波浪线
        if (this.interfereCount >= 1) {
            g.setColor(getRandomColor(120, 230, random));
            drawSmoothWave(g, random);
        }
    }

    /**
     * 绘制平滑波浪线干扰轨迹。
     *
     * @param g      图形上下文
     * @param random 随机数生成器
     */
    private void drawSmoothWave(Graphics2D g, ThreadLocalRandom random) {
        int amplitude = random.nextInt(8) + 5;        // 波动幅度
        int wavelength = random.nextInt(40) + 30;     // 波长
        double phase = random.nextDouble() * Math.PI * 2;

        // ✅ 关键：限制 baseY 在中间区域
        int centerY = height / 2;
        int verticalJitter = Math.max(5, height / 6); // 至少偏移5像素
        int baseY = centerY - verticalJitter + random.nextInt(verticalJitter * 2);

        g.setStroke(new BasicStroke(2.5f)); // 线宽

        int[] xPoints = new int[width];
        int[] yPoints = new int[width];
        for (int x = 0; x < width; x++) {
            int y = baseY + (int) (amplitude * Math.sin((double) x / wavelength * 2 * Math.PI + phase));
            // 限制 y 不要超出图像边界（可选）
            y = Math.max(amplitude, Math.min(y, height - amplitude));
            xPoints[x] = x;
            yPoints[x] = y;
        }
        g.drawPolyline(xPoints, yPoints, width);
    }

    /**
     * 生成指定 RGB 范围内的随机颜色。
     *
     * @param min    最小颜色值
     * @param max    最大颜色值
     * @param random 随机数生成器
     * @return 随机颜色
     */
    private Color getRandomColor(int min, int max, ThreadLocalRandom random) {
        int range = max - min;
        return new Color(
            min + random.nextInt(range),
            min + random.nextInt(range),
            min + random.nextInt(range)
        );
    }

    /**
     * 扭曲
     *
     * @param g     {@link Graphics}
     * @param w1    w1
     * @param h1    h1
     * @param color 颜色
     */
    private void shear(Graphics g, int w1, int h1, Color color) {
        shearX(g, w1, h1, color);
        shearY(g, w1, h1, color);
    }

    /**
     * X坐标扭曲
     *
     * @param g     {@link Graphics}
     * @param w1    宽
     * @param h1    高
     * @param color 颜色
     */
    private void shearX(Graphics g, int w1, int h1, Color color) {

        int period = RandomUtil.randomInt(this.width);

        int frames = 1;
        int phase = RandomUtil.randomInt(2);

        for (int i = 0; i < h1; i++) {
            double d = (double) (period >> 1) * Math.sin((double) i / (double) period + (6.2831853071795862D * (double) phase) / (double) frames);
            g.copyArea(0, i, w1, 1, (int) d, 0);
            g.setColor(color);
            g.drawLine((int) d, i, 0, i);
            g.drawLine((int) d + w1, i, w1, i);
        }

    }

    /**
     * Y坐标扭曲
     *
     * @param g     {@link Graphics}
     * @param w1    宽
     * @param h1    高
     * @param color 颜色
     */
    private void shearY(Graphics g, int w1, int h1, Color color) {

        int period = RandomUtil.randomInt(this.height >> 1);

        int frames = 20;
        int phase = 7;
        for (int i = 0; i < w1; i++) {
            double d = (double) (period >> 1) * Math.sin((double) i / (double) period + (6.2831853071795862D * (double) phase) / (double) frames);
            g.copyArea(i, 0, 1, h1, 0, (int) d);
            g.setColor(color);
            // 擦除原位置的痕迹
            g.drawLine(i, (int) d, i, 0);
            g.drawLine(i, (int) d + h1, i, h1);
        }

    }

}

package org.namewta.common.web.filter;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.namewta.common.core.utils.ServletUtils;
import org.namewta.common.core.utils.ip.ClientAddressResolver;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

/** 在授权、限流和审计前固定可信来源地址；非法可信链不进入业务处理。 */
public final class ClientAddressFilter extends OncePerRequestFilter {
    private final ClientAddressResolver resolver;

    public ClientAddressFilter(ClientAddressResolver resolver) {
        this.resolver = resolver;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
        throws ServletException, IOException {
        String address;
        try {
            address = resolver.resolve(request);
        } catch (IllegalArgumentException ignored) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }
        request.setAttribute(ServletUtils.CLIENT_IP_ATTRIBUTE, address);
        chain.doFilter(request, response);
    }
}

package org.namewta.common.web.filter;

import jakarta.servlet.*;
import jakarta.servlet.http.HttpServletRequest;
import org.namewta.common.core.utils.StringUtils;
import org.springframework.http.MediaType;

import java.io.IOException;

/**
 * 可重复读取请求体的过滤器，仅对 JSON 请求包装可重复消费的请求对象。
 *
 * @author wta
 */
public class RepeatableFilter implements Filter {

    /**
     * 过滤器初始化入口，当前无额外初始化逻辑。
     *
     * @param filterConfig 过滤器配置
     * @throws ServletException 过滤器初始化异常
     */
    @Override
    public void init(FilterConfig filterConfig) throws ServletException {

    }

    /**
     * 为 JSON 请求创建可重复读取的包装器，便于日志、验签等场景多次读取请求体。
     *
     * @param request  原始请求
     * @param response 当前响应
     * @param chain    过滤器链
     * @throws IOException      IO 异常
     * @throws ServletException Servlet 异常
     */
    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
        throws IOException, ServletException {
        ServletRequest requestWrapper = null;
        if (request instanceof HttpServletRequest
            && StringUtils.startsWithIgnoreCase(request.getContentType(), MediaType.APPLICATION_JSON_VALUE)) {
            requestWrapper = new RepeatedlyRequestWrapper((HttpServletRequest) request, response);
        }
        if (null == requestWrapper) {
            chain.doFilter(request, response);
        } else {
            chain.doFilter(requestWrapper, response);
        }
    }

    /**
     * 过滤器销毁入口，当前无额外资源需要释放。
     */
    @Override
    public void destroy() {

    }
}

package org.namewta.common.web.filter;

import cn.hutool.core.io.IoUtil;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.ServletResponse;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import org.namewta.common.core.constant.Constants;

import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

/**
 * 构建可重复读取输入流的请求包装器，缓存请求体以支持多次读取。
 *
 * @author wta
 */
public class RepeatedlyRequestWrapper extends HttpServletRequestWrapper {
    /**
     * 请求体字节数据。
     */
    private final byte[] body;

    /**
     * 读取原始请求体并缓存到内存，统一设置请求与响应编码。
     *
     * @param request  原始请求
     * @param response 当前响应
     * @throws IOException 读取请求体异常
     */
    public RepeatedlyRequestWrapper(HttpServletRequest request, ServletResponse response) throws IOException {
        super(request);
        request.setCharacterEncoding(Constants.UTF8);
        response.setCharacterEncoding(Constants.UTF8);

        body = IoUtil.readBytes(request.getInputStream(), false);
    }

    /**
     * 基于缓存的请求体构造字符读取器。
     *
     * @return 可重复读取的字符流
     * @throws IOException IO 异常
     */
    @Override
    public BufferedReader getReader() throws IOException {
        return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8));
    }

    /**
     * 返回基于缓存请求体重新生成的输入流。
     *
     * @return 可重复读取的输入流
     * @throws IOException IO 异常
     */
    @Override
    public ServletInputStream getInputStream() throws IOException {
        final ByteArrayInputStream bais = new ByteArrayInputStream(body);
        return new ServletInputStream() {
            /**
             * 读取缓存请求体的下一个字节。
             *
             * @return 下一个字节
             * @throws IOException IO 异常
             */
            @Override
            public int read() throws IOException {
                return bais.read();
            }

            /**
             * 返回缓存请求体剩余可读字节数。
             *
             * @return 剩余字节数
             * @throws IOException IO 异常
             */
            @Override
            public int available() throws IOException {
                return bais.available();
            }

            /**
             * 判断缓存请求体是否已读取完毕。
             *
             * @return 是否读取完毕
             */
            @Override
            public boolean isFinished() {
                return bais.available() == 0;
            }

            /**
             * 判断输入流是否可读。
             *
             * @return 固定为 true
             */
            @Override
            public boolean isReady() {
                return true;
            }

            /**
             * 设置异步读取监听器。
             *
             * @param readListener 读取监听器
             */
            @Override
            public void setReadListener(ReadListener readListener) {

            }
        };
    }

    /**
     * 返回请求体的实际 UTF-8 字节数。
     *
     * @return 请求体字节数
     */
    public int getBodyLength() {
        return body.length;
    }

    /**
     * 复制不超过指定上限的请求体前缀，避免日志截断再复制完整大正文。
     *
     * @param maxLength 最大字节数
     * @return 请求体前缀
     */
    public byte[] getBodyPrefix(int maxLength) {
        return Arrays.copyOf(body, Math.min(body.length, maxLength));
    }
}

package org.namewta.common.web.filter;

import jakarta.servlet.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.RequiredArgsConstructor;
import org.namewta.common.core.utils.StringUtils;
import org.namewta.common.web.config.properties.XssProperties;
import org.springframework.http.HttpMethod;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * 防止 XSS 攻击的过滤器，对非排除请求执行参数与请求体清洗。
 *
 * @author wta
 */
@RequiredArgsConstructor
public class XssFilter implements Filter {
    /**
     * 跳过 XSS 过滤的请求路径集合。
     */
    private final List<String> excludes = new ArrayList<>();

    private final XssProperties properties;

    /**
     * 初始化过滤器并加载配置中的排除路径。
     *
     * @param filterConfig 过滤器配置
     * @throws ServletException 过滤器初始化异常
     */
    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        if (properties.getExcludeUrls() != null) {
            excludes.addAll(properties.getExcludeUrls());
        }
    }

    /**
     * 对请求执行 XSS 包装处理，命中排除规则时直接放行。
     *
     * @param request  原始请求
     * @param response 当前响应
     * @param chain    过滤器链
     * @throws IOException      IO 异常
     * @throws ServletException Servlet 异常
     */
    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
        throws IOException, ServletException {
        HttpServletRequest req = (HttpServletRequest) request;
        HttpServletResponse resp = (HttpServletResponse) response;
        if (handleExcludeURL(req, resp)) {
            chain.doFilter(request, response);
            return;
        }
        XssHttpServletRequestWrapper xssRequest = new XssHttpServletRequestWrapper((HttpServletRequest) request);
        chain.doFilter(xssRequest, response);
    }

    /**
     * 判断当前请求是否需要跳过 XSS 过滤。
     *
     * @param request  当前请求
     * @param response 当前响应
     * @return true 表示跳过过滤
     */
    private boolean handleExcludeURL(HttpServletRequest request, HttpServletResponse response) {
        String url = request.getServletPath();
        String method = request.getMethod();
        // GET DELETE 不过滤
        if (method == null || HttpMethod.GET.matches(method) || HttpMethod.DELETE.matches(method)) {
            return true;
        }
        return StringUtils.matches(url, excludes);
    }

    /**
     * 过滤器销毁入口，当前无额外资源需要释放。
     */
    @Override
    public void destroy() {

    }
}

package org.namewta.common.web.filter;

import cn.hutool.core.io.IoUtil;
import cn.hutool.core.map.MapUtil;
import cn.hutool.core.util.ArrayUtil;
import cn.hutool.core.util.StrUtil;
import cn.hutool.http.HtmlUtil;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import org.namewta.common.core.utils.StringUtils;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * XSS 请求包装器，统一清洗参数与 JSON 请求体中的 HTML 标签内容。
 *
 * @author wta
 */
public class XssHttpServletRequestWrapper extends HttpServletRequestWrapper {

    /**
     * 使用原始请求构造 XSS 包装器。
     *
     * @param request 原始请求
     */
    public XssHttpServletRequestWrapper(HttpServletRequest request) {
        super(request);
    }

    /**
     * 获取并清洗单个请求参数。
     *
     * @param name 参数名
     * @return 清洗后的参数值
     */
    @Override
    public String getParameter(String name) {
        String value = super.getParameter(name);
        if (value == null) {
            return null;
        }
        return HtmlUtil.cleanHtmlTag(value).trim();
    }

    /**
     * 获取并清洗整组请求参数。
     *
     * @return 清洗后的参数映射
     */
    @Override
    public Map<String, String[]> getParameterMap() {
        Map<String, String[]> valueMap = super.getParameterMap();
        if (MapUtil.isEmpty(valueMap)) {
            return valueMap;
        }
        // 避免某些容器不允许改参数的情况 copy一份重新改
        Map<String, String[]> map = new HashMap<>(valueMap.size());
        map.putAll(valueMap);
        for (Map.Entry<String, String[]> entry : map.entrySet()) {
            String[] values = entry.getValue();
            if (values != null) {
                int length = values.length;
                String[] escapseValues = new String[length];
                for (int i = 0; i < length; i++) {
                    // 防xss攻击和过滤前后空格
                    escapseValues[i] = HtmlUtil.cleanHtmlTag(values[i]).trim();
                }
                map.put(entry.getKey(), escapseValues);
            }
        }
        return map;
    }

    /**
     * 获取并清洗指定参数的多值数组。
     *
     * @param name 参数名
     * @return 清洗后的参数值数组
     */
    @Override
    public String[] getParameterValues(String name) {
        String[] values = super.getParameterValues(name);
        if (ArrayUtil.isEmpty(values)) {
            return values;
        }
        int length = values.length;
        String[] escapseValues = new String[length];
        for (int i = 0; i < length; i++) {
            // 防xss攻击和过滤前后空格
            escapseValues[i] = HtmlUtil.cleanHtmlTag(values[i]).trim();
        }
        return escapseValues;
    }

    /**
     * 获取输入流并在 JSON 场景下对请求体执行清洗。
     *
     * @return 清洗后的输入流
     * @throws IOException 读取请求体异常
     */
    @Override
    public ServletInputStream getInputStream() throws IOException {
        // 非json类型，直接返回
        if (!isJsonRequest()) {
            return super.getInputStream();
        }

        // 为空，直接返回
        String json = StrUtil.str(IoUtil.readBytes(super.getInputStream(), false), StandardCharsets.UTF_8);
        if (StringUtils.isEmpty(json)) {
            return super.getInputStream();
        }

        // xss过滤
        json = HtmlUtil.cleanHtmlTag(json).trim();
        byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);
        final ByteArrayInputStream bis = IoUtil.toStream(jsonBytes);
        return new ServletInputStream() {
            /**
             * 判断清洗后的 JSON 流是否已读取完毕。
             *
             * @return 是否读取完毕
             */
            @Override
            public boolean isFinished() {
                return true;
            }

            /**
             * 判断清洗后的 JSON 流是否可读。
             *
             * @return 固定为 true
             */
            @Override
            public boolean isReady() {
                return true;
            }

            /**
             * 返回清洗后的 JSON 字节数。
             *
             * @return JSON 字节数
             * @throws IOException IO 异常
             */
            @Override
            public int available() throws IOException {
                return jsonBytes.length;
            }

            /**
             * 设置异步读取监听器。
             *
             * @param readListener 读取监听器
             */
            @Override
            public void setReadListener(ReadListener readListener) {
            }

            /**
             * 读取清洗后的 JSON 流下一个字节。
             *
             * @return 下一个字节
             * @throws IOException IO 异常
             */
            @Override
            public int read() throws IOException {
                return bis.read();
            }
        };
    }

    /**
     * 判断当前请求是否为 JSON 请求。
     *
     * @return true 表示 JSON 请求
     */
    public boolean isJsonRequest() {
        String header = super.getHeader(HttpHeaders.CONTENT_TYPE);
        return StringUtils.startsWithIgnoreCase(header, MediaType.APPLICATION_JSON_VALUE);
    }
}

package org.namewta.common.web.handler;

import cn.hutool.core.util.ObjectUtil;
import cn.hutool.core.util.RandomUtil;
import cn.hutool.http.HttpStatus;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.ConstraintViolation;
import jakarta.validation.ConstraintViolationException;
import org.namewta.common.core.validation.ValidationException;
import lombok.extern.slf4j.Slf4j;
import org.namewta.common.core.domain.R;
import org.namewta.common.core.exception.ServiceException;
import org.namewta.common.core.exception.SseException;
import org.namewta.common.core.exception.base.BaseException;
import org.namewta.common.core.utils.SpringUtils;
import org.namewta.common.core.utils.StreamUtils;
import org.namewta.common.json.utils.JsonUtils;
import org.namewta.common.json.utils.LogSanitizer;
import org.springframework.boot.json.JsonParseException;
import org.springframework.context.MessageSourceResolvable;
import org.springframework.context.support.DefaultMessageSourceResolvable;
import org.springframework.expression.ExpressionException;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.BindException;
import org.springframework.validation.FieldError;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingPathVariableException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.async.AsyncRequestTimeoutException;
import org.springframework.web.method.annotation.HandlerMethodValidationException;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.servlet.NoHandlerFoundException;

import java.io.IOException;
import java.util.List;
import java.util.Map;

/**
 * 全局异常处理器
 *
 * @author Lion Li
 */
@Slf4j
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * 请求方式不支持
     */
    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
    public R<Void> handleHttpRequestMethodNotSupported(HttpRequestMethodNotSupportedException e,
                                                       HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.error("请求地址'{}',不支持'{}'请求", requestURI, e.getMethod());
        return R.fail(HttpStatus.HTTP_BAD_METHOD, e.getMessage());
    }

    /**
     * 业务异常
     */
    @ExceptionHandler(ServiceException.class)
    public R<?> handleServiceException(ServiceException e, HttpServletRequest request) {
        log.error("请求处理失败，异常类型={}", LogSanitizer.failure(e));
        Integer code = e.getCode();
        R<Object> response = ObjectUtil.isNotNull(code) ? R.fail(code, e.getMessage()) : R.fail(e.getMessage());
        response.setData(e.getData());
        return response;
    }

    /**
     * 认证失败
     */
    @ResponseStatus(org.springframework.http.HttpStatus.UNAUTHORIZED)
    @ExceptionHandler(SseException.class)
    public String handleNotLoginException(SseException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.debug("请求地址'{}',认证失败'{}',无法访问系统资源", requestURI, LogSanitizer.failure(e));
        return JsonUtils.toJsonString(R.fail(HttpStatus.HTTP_UNAUTHORIZED, "认证失败，无法访问系统资源"));
    }

    /**
     * servlet异常
     */
    @ExceptionHandler(ServletException.class)
    public R<Void> handleServletException(ServletException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.error("请求地址'{}',发生未知异常，类型={}", requestURI, LogSanitizer.failure(e));
        return R.fail("发生未知异常，请联系管理员");
    }

    /**
     * 业务异常
     */
    @ExceptionHandler(BaseException.class)
    public R<Void> handleBaseException(BaseException e, HttpServletRequest request) {
        log.error("请求处理失败，异常类型={}", LogSanitizer.failure(e));
        return R.fail(e.getMessage());
    }

    /**
     * 请求路径中缺少必需的路径变量
     */
    @ExceptionHandler(MissingPathVariableException.class)
    public R<Void> handleMissingPathVariableException(MissingPathVariableException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.error("请求路径中缺少必需的路径变量'{}',发生系统异常.", requestURI);
        return R.fail(String.format("请求路径中缺少必需的路径变量[%s]", e.getVariableName()));
    }

    /**
     * 请求参数类型不匹配
     */
    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    public R<Void> handleMethodArgumentTypeMismatchException(MethodArgumentTypeMismatchException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.error("请求参数类型不匹配'{}',发生系统异常.", requestURI);
        return R.fail(String.format("请求参数类型不匹配，参数[%s]要求类型为：'%s'，但输入值为：'%s'", e.getName(), e.getRequiredType().getName(), e.getValue()));
    }

    /**
     * 找不到路由
     */
    @ExceptionHandler(NoHandlerFoundException.class)
    public R<Void> handleNoHandlerFoundException(NoHandlerFoundException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.error("请求地址'{}'不存在.", requestURI);
        return R.fail(HttpStatus.HTTP_NOT_FOUND, "请求地址不存在");
    }

    /**
     * 拦截未知的运行时异常
     */
    @ResponseStatus(org.springframework.http.HttpStatus.INTERNAL_SERVER_ERROR)
    @ExceptionHandler(IOException.class)
    public void handleIoException(IOException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        String path = SpringUtils.getProperty("message.path");
        if (requestURI.contains(path)) {
            // sse 经常性连接中断 例如关闭浏览器 直接屏蔽
            return;
        }
        log.error("请求地址'{}',连接中断，类型={}", requestURI, LogSanitizer.failure(e));
    }

    /**
     * sse 连接超时异常 不需要处理
     */
    @ExceptionHandler(AsyncRequestTimeoutException.class)
    public void handleRuntimeException(AsyncRequestTimeoutException e) {
    }

    /**
     * 拦截未知的运行时异常
     */
    @ExceptionHandler(RuntimeException.class)
    public R<Void> handleRuntimeException(RuntimeException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        String errorId = RandomUtil.randomNumbers(8);
        log.error("请求地址'{}',发生未知异常, 错误编号: {}，类型={}", requestURI, errorId, LogSanitizer.failure(e));
        return R.fail("发生未知异常，请联系管理员 [错误编号: " + errorId + "]");
    }

    /**
     * 系统异常
     */
    @ExceptionHandler(Exception.class)
    public R<Void> handleException(Exception e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        String errorId = RandomUtil.randomNumbers(8);
        log.error("请求地址'{}',发生系统异常, 错误编号: {}，类型={}", requestURI, errorId, LogSanitizer.failure(e));
        return R.fail("发生系统异常，请联系管理员 [错误编号: " + errorId + "]");
    }

    /**
     * 自定义验证异常
     */
    @ExceptionHandler(BindException.class)
    public R<Void> handleBindException(BindException e) {
        log.error("请求处理失败，异常类型={}", LogSanitizer.failure(e));
        String message = StreamUtils.join(e.getAllErrors(), DefaultMessageSourceResolvable::getDefaultMessage, ", ");
        R<Void> response = R.fail(message);
        response.setError(errorInfo(e.getAllErrors().stream().map(error -> new R.ErrorInfo(
            resolveCode(error.getDefaultMessage()), Map.of(), error instanceof FieldError field ? field.getField() : null, List.of())).toList()));
        return response;
    }

    /**
     * 自定义验证异常
     */
    @ExceptionHandler(ConstraintViolationException.class)
    public R<Void> constraintViolationException(ConstraintViolationException e) {
        log.error("请求处理失败，异常类型={}", LogSanitizer.failure(e));
        String message = StreamUtils.join(e.getConstraintViolations(), ConstraintViolation::getMessage, ", ");
        R<Void> response = R.fail(message);
        response.setError(errorInfo(e.getConstraintViolations().stream().map(v -> new R.ErrorInfo(
            resolveCode(v.getMessageTemplate()), Map.of(), v.getPropertyPath().toString(), List.of())).toList()));
        return response;
    }

    /**
     * 自定义验证异常
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public R<Void> handleMethodArgumentNotValidException(MethodArgumentNotValidException e) {
        log.error("请求处理失败，异常类型={}", LogSanitizer.failure(e));
        String message = StreamUtils.join(e.getBindingResult().getAllErrors(), DefaultMessageSourceResolvable::getDefaultMessage, ", ");
        R<Void> response = R.fail(message);
        response.setError(errorInfo(e.getBindingResult().getAllErrors().stream().map(error -> new R.ErrorInfo(
            resolveCode(error.getDefaultMessage()), Map.of(), error instanceof FieldError field ? field.getField() : null, List.of())).toList()));
        return response;
    }

    /**
     * 方法参数校验异常 用于处理 @Validated 注解
     */
    @ExceptionHandler(HandlerMethodValidationException.class)
    public R<Void> handlerMethodValidationException(HandlerMethodValidationException e) {
        log.error("请求处理失败，异常类型={}", LogSanitizer.failure(e));
        String message = StreamUtils.join(e.getAllErrors(), MessageSourceResolvable::getDefaultMessage, ", ");
        R<Void> response = R.fail(message);
        response.setError(errorInfo(e.getAllErrors().stream().map(error -> new R.ErrorInfo(
            resolveCode(error.getDefaultMessage()), Map.of(), null, List.of())).toList()));
        return response;
    }

    @ExceptionHandler(ValidationException.class)
    public R<Void> validationException(ValidationException e) {
        R<Void> response = R.fail(e.getMessage());
        List<R.ErrorInfo> errors = e.violations().stream()
            .map(issue -> new R.ErrorInfo(issue.code(), issue.args(), issue.field(), List.of())).toList();
        response.setError(errorInfo(errors));
        return response;
    }

    private R.ErrorInfo errorInfo(List<R.ErrorInfo> errors) {
        if (errors == null || errors.isEmpty()) {
            return new R.ErrorInfo("validation.format.invalid", Map.of(), null, List.of());
        }
        R.ErrorInfo first = errors.get(0);
        return new R.ErrorInfo(first.code(), first.args(), first.field(), errors);
    }

    private String resolveCode(String template) {
        if (template == null || template.isBlank()) return "validation.format.invalid";
        return template.startsWith("{") && template.endsWith("}")
            ? template.substring(1, template.length() - 1) : template;
    }

    /**
     * JSON 解析异常（Jackson 在处理 JSON 格式出错时抛出）
     * 可能是请求体格式非法，也可能是服务端反序列化失败
     */
    @ExceptionHandler(JsonParseException.class)
    public R<Void> handleJsonParseException(JsonParseException e, HttpServletRequest request) {
        String requestURI = request.getRequestURI();
        log.error("请求地址'{}' 发生 JSON 解析异常: {}", requestURI, LogSanitizer.failure(e));
        return R.fail(HttpStatus.HTTP_BAD_REQUEST, "请求数据格式错误");
    }

    /**
     * 请求体读取异常（通常是请求参数格式非法、字段类型不匹配等）
     */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    public R<Void> handleHttpMessageNotReadableException(HttpMessageNotReadableException e, HttpServletRequest request) {
        log.error("请求地址'{}', 参数解析失败: {}", request.getRequestURI(), LogSanitizer.failure(e));
        return R.fail(HttpStatus.HTTP_BAD_REQUEST, "请求参数格式错误");
    }

    /**
     * SpEL 表达式相关异常
     */
    @ExceptionHandler(ExpressionException.class)
    public R<Void> handleSpelException(ExpressionException e, HttpServletRequest request) {
        log.error("请求地址'{}'，SpEL解析异常: {}", request.getRequestURI(), LogSanitizer.failure(e));
        return R.fail(HttpStatus.HTTP_INTERNAL_ERROR, "SpEL解析失败：" + e.getMessage());
    }

}

package org.namewta.common.web.logging;

import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.CoreConstants;
import ch.qos.logback.core.pattern.CompositeConverter;

/**
 * 为 sys-console 文件选择行格式：HTTP 专用 logger 原样输出 JSON，其他日志沿用文本 pattern。
 */
public class SysConsoleLineConverter extends CompositeConverter<ILoggingEvent> {

    @Override
    protected String transform(ILoggingEvent event, String genericLine) {
        if (SysLogEventWriter.LOGGER_NAME.equals(event.getLoggerName())) {
            return event.getFormattedMessage() + CoreConstants.LINE_SEPARATOR;
        }
        return genericLine + CoreConstants.LINE_SEPARATOR;
    }
}

package org.namewta.common.web.logging;

import java.nio.charset.StandardCharsets;

/**
 * 一个方向的正文日志结果。
 */
record SysLogBody(boolean logged, long length, boolean truncated, String body, String omissionReason) {

    static SysLogBody logged(byte[] prefix, long fullLength, int maxBytes) {
        int availableLength = Math.min(prefix.length, maxBytes);
        int safeLength = fullLength > availableLength
            ? safeUtf8Length(prefix, availableLength)
            : availableLength;
        return new SysLogBody(
            true,
            fullLength,
            fullLength > safeLength,
            new String(prefix, 0, safeLength, StandardCharsets.UTF_8),
            null);
    }

    static SysLogBody omitted(long length, String reason) {
        return new SysLogBody(false, length, false, null, reason);
    }

    private static int safeUtf8Length(byte[] bytes, int limit) {
        if (limit == 0) {
            return limit;
        }
        int lead = limit - 1;
        while (lead >= 0 && (bytes[lead] & 0xC0) == 0x80) {
            lead--;
        }
        if (lead < 0) {
            return 0;
        }
        int first = bytes[lead] & 0xFF;
        int sequenceLength;
        if ((first & 0x80) == 0) {
            sequenceLength = 1;
        } else if ((first & 0xE0) == 0xC0) {
            sequenceLength = 2;
        } else if ((first & 0xF0) == 0xE0) {
            sequenceLength = 3;
        } else if ((first & 0xF8) == 0xF0) {
            sequenceLength = 4;
        } else {
            return lead;
        }
        return lead + sequenceLength <= limit ? limit : lead;
    }
}

package org.namewta.common.web.logging;

import org.namewta.common.json.utils.LogSanitizer;

/** 在 HTTP 日志副本中应用共享策略；不完整或非 JSON 正文只输出固定摘要。 */
final class SysLogBodySanitizer {

    private SysLogBodySanitizer() {
    }

    static SysLogBody sanitize(SysLogBody body, String contentType, String requestPath) {
        if (!body.logged()) {
            return body;
        }
        // 不完整前缀不能证明脱敏完成，绝不输出截断前的原始片段。
        String safe = !body.truncated() && SysLogMediaTypePolicy.isJson(contentType)
            ? LogSanitizer.json(body.body(), requestPath) : LogSanitizer.REDACTED;
        return new SysLogBody(true, body.length(), body.truncated(), safe, null);
    }
}

package org.namewta.common.web.logging;

import java.util.Map;

/**
 * HTTP 结构化事件输出接缝。
 */
@FunctionalInterface
public interface SysLogEventSink {

    /**
     * 输出一个完整 HTTP JSON 事件。
     *
     * @param event 事件字段
     */
    void write(Map<String, Object> event);
}

package org.namewta.common.web.logging;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import tools.jackson.databind.json.JsonMapper;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * 使用项目 JsonMapper 向专用 INFO logger 输出中文字段的完整单行事件。
 */
public class SysLogEventWriter implements SysLogEventSink {

    /**
     * Logback 用于识别无前缀 HTTP JSON 行的稳定 logger 名。
     */
    public static final String LOGGER_NAME = "org.namewta.system.http";

    private static final Logger HTTP_LOG = LoggerFactory.getLogger(LOGGER_NAME);
    private static final Map<String, String> FIELD_NAMES = Map.ofEntries(
        Map.entry("timestamp", "记录时间"),
        Map.entry("event", "事件类型"),
        Map.entry("requestId", "请求标识"),
        Map.entry("method", "请求方法"),
        Map.entry("path", "请求路径"),
        Map.entry("parameters", "请求参数"),
        Map.entry("requestHeaders", "请求头"),
        Map.entry("responseHeaders", "响应头"),
        Map.entry("contentType", "内容类型"),
        Map.entry("contentLength", "内容长度"),
        Map.entry("upstreamRequestId", "上游请求标识"),
        Map.entry("status", "响应状态"),
        Map.entry("durationMs", "耗时毫秒"),
        Map.entry("completed", "处理完成"),
        Map.entry("bodyLogged", "正文已记录"),
        Map.entry("bodyLength", "正文长度"),
        Map.entry("truncated", "正文已截断"),
        Map.entry("body", "正文"),
        Map.entry("bodyOmissionReason", "正文省略原因")
    );
    private static final Map<String, String> EVENT_NAMES = Map.of(
        "HTTP_REQUEST", "请求进入",
        "HTTP_RESPONSE", "响应返回"
    );
    private static final Map<String, String> BODY_OMISSION_REASONS = Map.ofEntries(
        Map.entry("NO_BODY", "无正文"),
        Map.entry("CREDENTIAL_RESPONSE", "凭据签发仅记录元数据"),
        Map.entry("CONTENT_TYPE_MISSING", "未提供内容类型"),
        Map.entry("INVALID_CONTENT_TYPE", "内容类型无效"),
        Map.entry("MULTIPART", "多部分表单"),
        Map.entry("FORM_PARAMETERS_ONLY", "仅记录表单参数"),
        Map.entry("NON_TEXT_CONTENT_TYPE", "非文本内容"),
        Map.entry("ATTACHMENT", "附件内容"),
        Map.entry("STREAMING", "流式内容"),
        Map.entry("BODY_CAPTURE_UNAVAILABLE", "正文采集不可用")
    );

    private final JsonMapper jsonMapper;

    public SysLogEventWriter(JsonMapper jsonMapper) {
        this.jsonMapper = jsonMapper;
    }

    @Override
    public void write(Map<String, Object> event) {
        Map<String, Object> localizedEvent = new LinkedHashMap<>();
        event.forEach((name, value) -> localizedEvent.put(
            FIELD_NAMES.getOrDefault(name, name), localizedValue(name, value)));
        HTTP_LOG.info(jsonMapper.writeValueAsString(localizedEvent));
    }

    private Object localizedValue(String name, Object value) {
        if ("event".equals(name) && value instanceof String eventName) {
            return EVENT_NAMES.getOrDefault(eventName, eventName);
        }
        if ("bodyOmissionReason".equals(name) && value instanceof String omissionReason) {
            return BODY_OMISSION_REASONS.getOrDefault(omissionReason, omissionReason);
        }
        return value;
    }
}

package org.namewta.common.web.logging;

import jakarta.servlet.AsyncContext;
import jakarta.servlet.AsyncEvent;
import jakarta.servlet.AsyncListener;
import jakarta.servlet.Filter;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletRequest;
import jakarta.servlet.ServletResponse;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.namewta.common.web.filter.RepeatedlyRequestWrapper;
import org.namewta.common.json.utils.LogSanitizer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;

import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Enumeration;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 在 Servlet Filter 边界记录一对可关联的请求与响应 JSON 事件。
 */
public class SysLogFilter implements Filter {

    public static final String REQUEST_ID_HEADER = "X-Request-Id";
    public static final String MDC_REQUEST_ID = "requestId";

    private static final String STATE_ATTRIBUTE = SysLogFilter.class.getName() + ".exchange";
    private static final String REDACTED_HEADER_VALUE = "[REDACTED]";
    private static final Logger FAILURE_LOG = LoggerFactory.getLogger(SysLogFilter.class);

    private final int maxBodyBytes;
    private final SysLogEventSink eventSink;

    public SysLogFilter(int maxBodyBytes, SysLogEventSink eventSink) {
        if (maxBodyBytes <= 0) {
            throw new IllegalArgumentException("正文日志字节上限必须大于 0");
        }
        this.maxBodyBytes = maxBodyBytes;
        this.eventSink = eventSink;
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
        throws IOException, ServletException {
        if (!(request instanceof HttpServletRequest httpRequest)
            || !(response instanceof HttpServletResponse httpResponse)) {
            chain.doFilter(request, response);
            return;
        }

        ExchangeState state = (ExchangeState) httpRequest.getAttribute(STATE_ATTRIBUTE);
        HttpServletRequest effectiveRequest = httpRequest;
        boolean initialDispatch = state == null;
        if (initialDispatch) {
            effectiveRequest = prepareRequest(httpRequest, httpResponse);
            state = new ExchangeState(effectiveRequest, maxBodyBytes);
            effectiveRequest.setAttribute(STATE_ATTRIBUTE, state);
            httpResponse.setHeader(REQUEST_ID_HEADER, state.requestId());
        }

        SysLogResponseWrapper effectiveResponse = wrapResponse(httpResponse, state.responseCapture());
        state.updateResponse(effectiveResponse);
        String previousRequestId = MDC.get(MDC_REQUEST_ID);
        MDC.put(MDC_REQUEST_ID, state.requestId());
        try {
            if (initialDispatch) {
                emit(state.requestEvent(effectiveRequest));
            }
            chain.doFilter(effectiveRequest, effectiveResponse);
            if (effectiveRequest.isAsyncStarted()) {
                state.registerAsync(effectiveRequest.getAsyncContext(), effectiveRequest, effectiveResponse);
            } else {
                state.finish(true, effectiveResponse);
            }
        } catch (IOException | ServletException | RuntimeException | Error exception) {
            state.finish(false, effectiveResponse);
            throw exception;
        } finally {
            restoreMdc(previousRequestId);
        }
    }

    private HttpServletRequest prepareRequest(HttpServletRequest request, HttpServletResponse response) {
        if (request instanceof RepeatedlyRequestWrapper
            || !SysLogMediaTypePolicy.isRequestBodyLoggable(request.getContentType())) {
            return request;
        }
        try {
            return new RepeatedlyRequestWrapper(request, response);
        } catch (IOException | RuntimeException exception) {
            reportFailure("请求正文采集", null, exception);
            return request;
        }
    }

    private SysLogResponseWrapper wrapResponse(HttpServletResponse response, SysLogResponseCapture capture) {
        if (response instanceof SysLogResponseWrapper wrapper && wrapper.uses(capture)) {
            return wrapper;
        }
        return new SysLogResponseWrapper(response, capture);
    }

    private void emit(Map<String, Object> event) {
        try {
            eventSink.write(event);
        } catch (RuntimeException | LinkageError exception) {
            String eventName = String.valueOf(event.get("event"));
            String stage = switch (eventName) {
                case "HTTP_REQUEST" -> "请求事件输出";
                case "HTTP_RESPONSE" -> "响应事件输出";
                default -> eventName;
            };
            reportFailure(stage, String.valueOf(event.get("requestId")), exception);
        }
    }

    private void reportFailure(String stage, String requestId, Throwable failure) {
        try {
            FAILURE_LOG.error("系统 HTTP 日志采集失败：阶段={}，请求标识={}，异常类型={}", stage, requestId, LogSanitizer.failure(failure));
        } catch (RuntimeException | LinkageError terminalFailure) {
            System.err.printf("系统 HTTP 日志采集失败：阶段=%s，请求标识=%s，原因=%s%n",
                stage, requestId, LogSanitizer.failure(failure));
        }
    }

    private void restoreMdc(String requestId) {
        if (requestId == null) {
            MDC.remove(MDC_REQUEST_ID);
        } else {
            MDC.put(MDC_REQUEST_ID, requestId);
        }
    }

    private Map<String, List<String>> requestHeaders(HttpServletRequest request) {
        Map<String, List<String>> headers = new LinkedHashMap<>();
        try {
            Enumeration<String> names = request.getHeaderNames();
            if (names == null) {
                return headers;
            }
            while (names.hasMoreElements()) {
                String name = names.nextElement();
                headers.put(name, isSensitiveHeader(name)
                    ? List.of(REDACTED_HEADER_VALUE)
                    : enumerationValues(request.getHeaders(name)));
            }
        } catch (RuntimeException exception) {
            reportFailure("请求头采集", null, exception);
        }
        return headers;
    }

    private Map<String, List<String>> requestParameters(HttpServletRequest request) {
        Map<String, List<String>> parameters = new LinkedHashMap<>();
        try {
            request.getParameterMap().forEach((name, values) ->
                parameters.put(name, LogSanitizer.isSensitiveName(name, requestPath(request))
                    ? List.of(REDACTED_HEADER_VALUE)
                    : values == null ? List.of() : Arrays.asList(values.clone())));
        } catch (RuntimeException exception) {
            reportFailure("请求参数采集", null, exception);
        }
        return parameters;
    }

    private Map<String, List<String>> responseHeaders(HttpServletResponse response) {
        Map<String, List<String>> headers = new LinkedHashMap<>();
        try {
            for (String name : response.getHeaderNames()) {
                headers.put(name, isSensitiveHeader(name)
                    ? List.of(REDACTED_HEADER_VALUE)
                    : new ArrayList<>(response.getHeaders(name)));
            }
        } catch (RuntimeException exception) {
            reportFailure("响应头采集", null, exception);
        }
        return headers;
    }

    private boolean isSensitiveHeader(String name) {
        return LogSanitizer.isSensitiveHeader(name);
    }

    private List<String> enumerationValues(Enumeration<String> values) {
        List<String> result = new ArrayList<>();
        if (values != null) {
            while (values.hasMoreElements()) {
                result.add(values.nextElement());
            }
        }
        return result;
    }

    private SysLogBody requestBody(HttpServletRequest request, int limit) {
        long contentLength = request.getContentLengthLong();
        if (contentLength == 0) {
            return SysLogBody.omitted(0, "NO_BODY");
        }
        SysLogMediaTypePolicy.BodyDecision decision = SysLogMediaTypePolicy.requestDecision(request.getContentType());
        if (!decision.loggable()) {
            return SysLogBody.omitted(0, decision.omissionReason());
        }
        if (request instanceof RepeatedlyRequestWrapper wrapper) {
            if (wrapper.getBodyLength() == 0) {
                return SysLogBody.omitted(0, "NO_BODY");
            }
            return SysLogBody.logged(wrapper.getBodyPrefix(limit), wrapper.getBodyLength(), limit);
        }
        return SysLogBody.omitted(0, "BODY_CAPTURE_UNAVAILABLE");
    }

    private String requestPath(HttpServletRequest request) {
        String servletPath = request.getServletPath();
        return servletPath == null || servletPath.isEmpty()
            ? request.getRequestURI().substring(request.getContextPath().length()) : servletPath;
    }

    private long responseContentLength(HttpServletResponse response) {
        String value = response.getHeader("Content-Length");
        if (value == null) {
            return -1;
        }
        try {
            return Long.parseLong(value);
        } catch (NumberFormatException ignored) {
            return -1;
        }
    }

    private void putBody(Map<String, Object> event, SysLogBody body, String contentType, String requestPath) {
        body = SysLogBodySanitizer.sanitize(body, contentType, requestPath);
        event.put("bodyLogged", body.logged());
        event.put("bodyLength", body.length());
        event.put("truncated", body.truncated());
        if (body.logged()) {
            event.put("body", body.body());
        } else {
            event.put("bodyOmissionReason", body.omissionReason());
        }
    }

    private final class ExchangeState {

        private final String requestId = UUID.randomUUID().toString();
        private final String method;
        private final String path;
        private final long startNanos = System.nanoTime();
        private final int bodyLimit;
        private final SysLogResponseCapture responseCapture;
        private final AtomicBoolean finished = new AtomicBoolean();
        private final CompletionListener completionListener = new CompletionListener(this);
        private volatile HttpServletResponse currentResponse;
        private AsyncContext registeredAsyncContext;

        private ExchangeState(HttpServletRequest request, int bodyLimit) {
            this.method = request.getMethod();
            this.path = requestPath(request);
            this.bodyLimit = bodyLimit;
            this.responseCapture = new SysLogResponseCapture(bodyLimit);
        }

        private String requestId() {
            return requestId;
        }

        private SysLogResponseCapture responseCapture() {
            return responseCapture;
        }

        private void updateResponse(HttpServletResponse response) {
            currentResponse = response;
        }

        private Map<String, Object> requestEvent(HttpServletRequest request) {
            Map<String, Object> event = new LinkedHashMap<>();
            event.put("timestamp", Instant.now().toString());
            event.put("event", "HTTP_REQUEST");
            event.put("requestId", requestId);
            event.put("method", method);
            event.put("path", path);
            event.put("parameters", requestParameters(request));
            event.put("requestHeaders", requestHeaders(request));
            event.put("contentType", request.getContentType());
            event.put("contentLength", request.getContentLengthLong());
            String upstreamRequestId = request.getHeader(REQUEST_ID_HEADER);
            if (upstreamRequestId != null) {
                event.put("upstreamRequestId", upstreamRequestId);
            }
            putBody(event, requestBody(request, bodyLimit), request.getContentType(), path);
            return event;
        }

        private synchronized void registerAsync(AsyncContext asyncContext,
                                                HttpServletRequest request,
                                                HttpServletResponse response) {
            if (finished.get() || registeredAsyncContext == asyncContext) {
                return;
            }
            try {
                asyncContext.addListener(completionListener, request, response);
                registeredAsyncContext = asyncContext;
            } catch (IllegalStateException exception) {
                reportFailure("异步监听器注册", requestId, exception);
                finish(false, response);
            }
        }

        private synchronized void asyncRestarted(AsyncContext asyncContext,
                                                 HttpServletRequest request,
                                                 HttpServletResponse response) {
            registeredAsyncContext = null;
            registerAsync(asyncContext, request, response);
        }

        private void finish(boolean completed, HttpServletResponse suppliedResponse) {
            if (!finished.compareAndSet(false, true)) {
                return;
            }
            HttpServletResponse response = suppliedResponse == null ? currentResponse : suppliedResponse;
            if (response == null) {
                return;
            }
            String previousRequestId = MDC.get(MDC_REQUEST_ID);
            MDC.put(MDC_REQUEST_ID, requestId);
            try {
                if (response instanceof SysLogResponseWrapper wrapper) {
                    wrapper.flushForLogging();
                }
                Map<String, Object> event = new LinkedHashMap<>();
                event.put("timestamp", Instant.now().toString());
                event.put("event", "HTTP_RESPONSE");
                event.put("requestId", requestId);
                event.put("method", method);
                event.put("path", path);
                event.put("status", response.getStatus());
                event.put("responseHeaders", responseHeaders(response));
                event.put("contentType", response.getContentType());
                event.put("contentLength", responseContentLength(response));
                event.put("durationMs", Math.max(0, (System.nanoTime() - startNanos) / 1_000_000));
                event.put("completed", completed);
                SysLogBody body = responseCapture.snapshot(response);
                if (LogSanitizer.omitResponseBody(path)) {
                    body = SysLogBody.omitted(body.length(), "CREDENTIAL_RESPONSE");
                }
                putBody(event, body, response.getContentType(), path);
                emit(event);
            } finally {
                restoreMdc(previousRequestId);
            }
        }
    }

    private final class CompletionListener implements AsyncListener {

        private final ExchangeState state;

        private CompletionListener(ExchangeState state) {
            this.state = state;
        }

        @Override
        public void onComplete(AsyncEvent event) {
            state.finish(true, suppliedResponse(event));
        }

        @Override
        public void onTimeout(AsyncEvent event) {
            state.finish(false, suppliedResponse(event));
        }

        @Override
        public void onError(AsyncEvent event) {
            state.finish(false, suppliedResponse(event));
        }

        @Override
        public void onStartAsync(AsyncEvent event) {
            ServletRequest request = event.getSuppliedRequest();
            ServletResponse response = event.getSuppliedResponse();
            if (request instanceof HttpServletRequest httpRequest
                && response instanceof HttpServletResponse httpResponse) {
                state.asyncRestarted(event.getAsyncContext(), httpRequest, httpResponse);
            }
        }

        private HttpServletResponse suppliedResponse(AsyncEvent event) {
            return event.getSuppliedResponse() instanceof HttpServletResponse response ? response : null;
        }
    }
}

package org.namewta.common.web.logging;

import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.InvalidMediaTypeException;
import org.springframework.http.MediaType;

import java.util.Locale;

/**
 * 系统日志正文分类策略。文件、二进制和持续流只允许记录元数据。
 */
public final class SysLogMediaTypePolicy {

    private static final String CONTENT_DISPOSITION = "Content-Disposition";

    private SysLogMediaTypePolicy() {
    }

    /**
     * 判断请求正文是否属于可重复读取并记录的普通文本。
     *
     * @param contentType 请求 Content-Type
     * @return 是否记录正文
     */
    public static boolean isRequestBodyLoggable(String contentType) {
        BodyDecision decision = requestDecision(contentType);
        return decision.loggable();
    }

    static BodyDecision requestDecision(String contentType) {
        MediaType mediaType = parse(contentType);
        if (mediaType == null) {
            return BodyDecision.omit(contentType == null ? "CONTENT_TYPE_MISSING" : "INVALID_CONTENT_TYPE");
        }
        if ("multipart".equalsIgnoreCase(mediaType.getType())) {
            return BodyDecision.omit("MULTIPART");
        }
        if (MediaType.APPLICATION_FORM_URLENCODED.isCompatibleWith(mediaType)) {
            return BodyDecision.omit("FORM_PARAMETERS_ONLY");
        }
        return isTextual(mediaType) ? BodyDecision.allow() : BodyDecision.omit("NON_TEXT_CONTENT_TYPE");
    }

    static BodyDecision responseDecision(HttpServletResponse response) {
        String disposition = response.getHeader(CONTENT_DISPOSITION);
        if (disposition != null && disposition.toLowerCase(Locale.ROOT).contains("attachment")) {
            return BodyDecision.omit("ATTACHMENT");
        }
        MediaType mediaType = parse(response.getContentType());
        if (mediaType == null) {
            return BodyDecision.omit(response.getContentType() == null
                ? "CONTENT_TYPE_MISSING" : "INVALID_CONTENT_TYPE");
        }
        if (MediaType.TEXT_EVENT_STREAM.isCompatibleWith(mediaType)) {
            return BodyDecision.omit("STREAMING");
        }
        return isTextual(mediaType) ? BodyDecision.allow() : BodyDecision.omit("NON_TEXT_CONTENT_TYPE");
    }

    static boolean isJson(String contentType) {
        MediaType mediaType = parse(contentType);
        if (mediaType == null) {
            return false;
        }
        String subtype = mediaType.getSubtype().toLowerCase(Locale.ROOT);
        return MediaType.APPLICATION_JSON.isCompatibleWith(mediaType) || subtype.endsWith("+json");
    }

    private static MediaType parse(String contentType) {
        if (contentType == null || contentType.isBlank()) {
            return null;
        }
        try {
            return MediaType.parseMediaType(contentType);
        } catch (InvalidMediaTypeException ignored) {
            return null;
        }
    }

    private static boolean isTextual(MediaType mediaType) {
        String subtype = mediaType.getSubtype().toLowerCase(Locale.ROOT);
        return "text".equalsIgnoreCase(mediaType.getType())
            || MediaType.APPLICATION_JSON.isCompatibleWith(mediaType)
            || subtype.endsWith("+json")
            || MediaType.APPLICATION_XML.isCompatibleWith(mediaType)
            || subtype.endsWith("+xml")
            || "javascript".equals(subtype)
            || "graphql".equals(subtype);
    }

    record BodyDecision(boolean loggable, String omissionReason) {

        static BodyDecision allow() {
            return new BodyDecision(true, null);
        }

        static BodyDecision omit(String reason) {
            return new BodyDecision(false, reason);
        }
    }
}

package org.namewta.common.web.logging;

import jakarta.servlet.http.HttpServletResponse;

import java.io.ByteArrayOutputStream;

/**
 * 响应直通写出时的有界日志副本；无论是否记录正文，都统计实际观察到的写出字节。
 */
final class SysLogResponseCapture {

    private final int maxBodyBytes;
    private final ByteArrayOutputStream prefix;
    private long bodyLength;
    private boolean missedBytes;

    SysLogResponseCapture(int maxBodyBytes) {
        this.maxBodyBytes = maxBodyBytes;
        this.prefix = new ByteArrayOutputStream(Math.min(maxBodyBytes, 8192));
    }

    synchronized void capture(int value, HttpServletResponse response) {
        bodyLength++;
        if (SysLogMediaTypePolicy.responseDecision(response).loggable()) {
            if (!missedBytes && prefix.size() < maxBodyBytes) {
                prefix.write(value);
            }
        } else {
            missedBytes = true;
        }
    }

    synchronized void capture(byte[] bytes, int offset, int length, HttpServletResponse response) {
        bodyLength += length;
        if (SysLogMediaTypePolicy.responseDecision(response).loggable()) {
            if (!missedBytes && prefix.size() < maxBodyBytes) {
                int copyLength = Math.min(length, maxBodyBytes - prefix.size());
                prefix.write(bytes, offset, copyLength);
            }
        } else {
            missedBytes = true;
        }
    }

    synchronized void reset() {
        prefix.reset();
        bodyLength = 0;
        missedBytes = false;
    }

    synchronized SysLogBody snapshot(HttpServletResponse response) {
        if (bodyLength == 0) {
            return SysLogBody.omitted(0, "NO_BODY");
        }
        SysLogMediaTypePolicy.BodyDecision decision = SysLogMediaTypePolicy.responseDecision(response);
        if (!decision.loggable()) {
            return SysLogBody.omitted(bodyLength, decision.omissionReason());
        }
        if (missedBytes) {
            return SysLogBody.omitted(bodyLength, "BODY_CAPTURE_UNAVAILABLE");
        }
        return SysLogBody.logged(prefix.toByteArray(), bodyLength, maxBodyBytes);
    }
}

package org.namewta.common.web.logging;

import jakarta.servlet.ServletOutputStream;
import jakarta.servlet.WriteListener;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpServletResponseWrapper;

import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;

/**
 * 将响应字节直接写给下游响应，同时复制有界日志前缀。
 */
final class SysLogResponseWrapper extends HttpServletResponseWrapper {

    private final SysLogResponseCapture capture;
    private CapturingServletOutputStream outputStream;
    private PrintWriter writer;
    private boolean outputStreamRequested;

    SysLogResponseWrapper(HttpServletResponse response, SysLogResponseCapture capture) {
        super(response);
        this.capture = capture;
    }

    boolean uses(SysLogResponseCapture expectedCapture) {
        return capture == expectedCapture;
    }

    void flushForLogging() {
        if (writer != null) {
            writer.flush();
        }
    }

    @Override
    public ServletOutputStream getOutputStream() throws IOException {
        if (writer != null) {
            throw new IllegalStateException("getWriter() has already been called for this response");
        }
        outputStreamRequested = true;
        return outputStream();
    }

    @Override
    public PrintWriter getWriter() throws IOException {
        if (outputStreamRequested) {
            throw new IllegalStateException("getOutputStream() has already been called for this response");
        }
        if (writer == null) {
            String encoding = getCharacterEncoding();
            Charset charset = encoding == null ? StandardCharsets.UTF_8 : Charset.forName(encoding);
            writer = new PrintWriter(new OutputStreamWriter(outputStream(), charset));
        }
        return writer;
    }

    @Override
    public void flushBuffer() throws IOException {
        if (writer != null) {
            writer.flush();
        } else if (outputStream != null) {
            outputStream.flush();
        }
        super.flushBuffer();
    }

    @Override
    public void reset() {
        super.reset();
        capture.reset();
    }

    @Override
    public void resetBuffer() {
        super.resetBuffer();
        capture.reset();
    }

    private CapturingServletOutputStream outputStream() throws IOException {
        if (outputStream == null) {
            outputStream = new CapturingServletOutputStream(super.getOutputStream());
        }
        return outputStream;
    }

    private final class CapturingServletOutputStream extends ServletOutputStream {

        private final ServletOutputStream delegate;

        private CapturingServletOutputStream(ServletOutputStream delegate) {
            this.delegate = delegate;
        }

        @Override
        public boolean isReady() {
            return delegate.isReady();
        }

        @Override
        public void setWriteListener(WriteListener writeListener) {
            delegate.setWriteListener(writeListener);
        }

        @Override
        public void write(int value) throws IOException {
            delegate.write(value);
            capture.capture(value, SysLogResponseWrapper.this);
        }

        @Override
        public void write(byte[] bytes, int offset, int length) throws IOException {
            delegate.write(bytes, offset, length);
            capture.capture(bytes, offset, length, SysLogResponseWrapper.this);
        }

        @Override
        public void flush() throws IOException {
            delegate.flush();
        }

        @Override
        public void close() throws IOException {
            delegate.close();
        }
    }
}

