package org.namewta.common.web.config;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.namewta.common.web.config.properties.ClientAddressProperties;
import org.namewta.common.web.filter.ClientAddressFilter;
import org.springframework.boot.autoconfigure.AutoConfigurations;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;

import static org.assertj.core.api.Assertions.assertThat;

@Tag("dev")
class ClientAddressConfigTest {
    private final ApplicationContextRunner runner = new ApplicationContextRunner()
        .withConfiguration(AutoConfigurations.of(ClientAddressConfig.class));

    @Test
    void defaultAndEmptyEnvironmentTrustNoProxy() {
        runner.run(context -> {
            assertThat(context).hasNotFailed().hasSingleBean(ClientAddressFilter.class);
            assertThat(context.getBean(ClientAddressProperties.class).getTrustedProxies()).isEmpty();
        });
        runner.withPropertyValues("namewta.web.client-address.trusted-proxies=").run(context -> {
            assertThat(context).hasNotFailed();
            assertThat(context.getBean(ClientAddressProperties.class).getTrustedProxies()).isEmpty();
        });
    }

    @Test
    void bindsExplicitCidrsAndRejectsMalformedTrustOrContainerRewriting() {
        runner.withPropertyValues("namewta.web.client-address.trusted-proxies=10.0.0.0/24,2001:db8::/64")
            .run(context -> {
                assertThat(context).hasNotFailed();
                assertThat(context.getBean(ClientAddressProperties.class).getTrustedProxies())
                    .containsExactly("10.0.0.0/24", "2001:db8::/64");
            });
        runner.withPropertyValues("namewta.web.client-address.trusted-proxies=localhost/32")
            .run(context -> assertThat(context).hasFailed());
        for (String strategy : new String[]{"native", "framework"}) {
            runner.withPropertyValues("server.forward-headers-strategy=" + strategy)
                .run(context -> assertThat(context).hasFailed());
        }
    }
}

package org.namewta.common.web.config;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.namewta.common.web.config.properties.CorsProperties;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@Tag("dev")
class CorsPolicyTest {
    @Test
    void unknownCredentialedOriginCannotReachLogin() throws Exception {
        var request = new MockHttpServletRequest("POST", "/sso/login");
        request.setServerName("sso.example.test");
        request.setScheme("https");
        request.setServerPort(443);
        request.addHeader("Origin", "https://unknown.example.test");
        var response = new MockHttpServletResponse();
        var reached = new AtomicBoolean();
        new ResourcesConfig().corsFilter(new CorsProperties()).doFilter(request, response,
            (req, res) -> reached.set(true));
        assertThat(response.getStatus()).isEqualTo(403);
        assertThat(reached).isFalse();
        assertThat(response.getHeader("Access-Control-Allow-Origin")).isNull();
        assertThat(response.getHeader("Access-Control-Allow-Credentials")).isNull();
    }

    @Test
    void approvedExactOriginPassesPreflightAndCredentialsButLookalikesDoNot() throws Exception {
        var properties = new CorsProperties();
        properties.setAllowedOrigins(List.of("https://sso.example.test", "http://127.0.0.1:4176"));
        for (String origin : List.of("https://sso.example.test", "http://127.0.0.1:4176",
            "https://sso.example.test.attacker.test", "https://sso.example.test:444", "null")) {
            var request = new MockHttpServletRequest("OPTIONS", "/sso/login");
            request.setServerName("backend.example.test");
            request.addHeader("Origin", origin);
            request.addHeader("Access-Control-Request-Method", "POST");
            request.addHeader("Access-Control-Request-Headers", "Content-Type");
            var response = new MockHttpServletResponse();
            new ResourcesConfig().corsFilter(properties).doFilter(request, response, (req, res) -> { });
            if (properties.getAllowedOrigins().contains(origin)) {
                assertThat(response.getStatus()).isEqualTo(200);
                assertThat(response.getHeader("Access-Control-Allow-Origin")).isEqualTo(origin);
                assertThat(response.getHeader("Access-Control-Allow-Credentials")).isEqualTo("true");
                assertThat(response.getHeader("Access-Control-Allow-Methods")).contains("POST");
            } else {
                assertThat(response.getStatus()).isEqualTo(403);
                assertThat(response.getHeader("Access-Control-Allow-Origin")).isNull();
            }
        }
    }

    @Test
    void invalidOrWildcardOriginConfigurationIsRejected() {
        for (String invalid : List.of("*", "https://*.example.test", "null", "file:///tmp", "https://user@example.test",
            "https://example.test/", "https://example.test/path", "https://example.test?x=1",
            "https://example.test#fragment", "https://example.test:65536")) {
            var properties = new CorsProperties();
            properties.setAllowedOrigins(List.of(invalid));
            assertThatThrownBy(() -> new ResourcesConfig().corsFilter(properties)).as(invalid)
                .isInstanceOf(IllegalArgumentException.class);
        }
    }
}

package org.namewta.common.web.config;

import org.namewta.common.web.logging.SysLogFilter;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.springframework.boot.autoconfigure.AutoConfigurations;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.boot.web.servlet.FilterRegistration;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import tools.jackson.databind.json.JsonMapper;

import java.lang.reflect.Method;

import static org.assertj.core.api.Assertions.assertThat;

@Tag("dev")
class SysLogConfigTest {

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner()
        .withConfiguration(AutoConfigurations.of(SysLogConfig.class))
        .withBean(JsonMapper.class, () -> JsonMapper.builder().build());

    @Test
    void enablesFilterByDefaultAndAllowsExplicitDisable() {
        contextRunner.run(context -> {
            assertThat(context).hasNotFailed();
            assertThat(context).hasSingleBean(SysLogFilter.class);
            assertThat(context.getBean(SysLogProperties.class).getMaxBodySize().toBytes())
                .isEqualTo(1024 * 1024);
        });

        contextRunner.withPropertyValues("sys.log.enabled=false").run(context -> {
            assertThat(context).hasNotFailed();
            assertThat(context).doesNotHaveBean(SysLogFilter.class);
        });
    }

    @Test
    void rejectsZeroAndNegativeBodyLimits() {
        contextRunner.withPropertyValues("sys.log.max-body-size=0B")
            .run(context -> assertThat(context).hasFailed());
        contextRunner.withPropertyValues("sys.log.max-body-size=-1B")
            .run(context -> assertThat(context).hasFailed());
        contextRunner.withPropertyValues("sys.log.max-body-size=not-a-size")
            .run(context -> assertThat(context).hasFailed());
    }

    @Test
    void filterOrderKeepsLoggingAfterRepeatableAndBeforeXss() {
        int repeatableOrder = registration(FilterConfig.class, "repeatableFilter").order();
        int sysLogOrder = registration(SysLogConfig.class, "sysLogFilter").order();
        int xssOrder = registration(FilterConfig.class, "xssFilter").order();

        assertThat(repeatableOrder).isEqualTo(FilterRegistrationBean.HIGHEST_PRECEDENCE + 1);
        assertThat(sysLogOrder).isEqualTo(repeatableOrder + 1);
        assertThat(xssOrder).isEqualTo(sysLogOrder + 1);
    }

    private FilterRegistration registration(Class<?> configurationClass, String methodName) {
        for (Method method : configurationClass.getDeclaredMethods()) {
            if (method.getName().equals(methodName)) {
                return method.getAnnotation(FilterRegistration.class);
            }
        }
        throw new AssertionError("Missing filter registration method " + methodName);
    }
}

package org.namewta.common.web.filter;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.namewta.common.core.utils.NetUtils;
import org.namewta.common.core.utils.ServletUtils;
import org.namewta.common.core.utils.ip.ClientAddressResolver;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@Tag("dev")
class ClientAddressFilterTest {
    @Test
    void defaultAndUntrustedPeersIgnoreAllForwardingHeaders() {
        var request = request("198.51.100.21", "192.0.2.77");
        for (String header : List.of("Forwarded", "X-Real-IP", "Proxy-Client-IP", "WL-Proxy-Client-IP",
            "HTTP_CLIENT_IP", "HTTP_X_FORWARDED_FOR")) {
            request.addHeader(header, "192.0.2.77");
        }
        assertThat(new ClientAddressResolver(List.of()).resolve(request)).isEqualTo("198.51.100.21");
        assertThat(resolver().resolve(request)).isEqualTo("198.51.100.21");
        request.removeHeader("X-Forwarded-For");
        request.addHeader("X-Forwarded-For", "not even an address");
        assertThat(resolver().resolve(request)).isEqualTo("198.51.100.21");
        assertThat(new ClientAddressResolver(List.of()).resolve(request("10.0.0.1", "192.0.2.77")))
            .isEqualTo("10.0.0.1");
    }

    @Test
    void peelsOnlyTrustedHopsFromRightAndSupportsRepeatedHeaders() {
        assertThat(resolver().resolve(request("10.0.0.2", "192.0.2.77, 198.51.100.21, 10.0.0.1")))
            .isEqualTo("198.51.100.21");
        var repeated = request("10.0.0.2", "192.0.2.77, 198.51.100.21");
        repeated.addHeader("X-Forwarded-For", "10.0.0.1");
        assertThat(resolver().resolve(repeated)).isEqualTo("198.51.100.21");
        assertThat(resolver().resolve(request("10.0.0.2", "198.51.100.21")))
            .isEqualTo("198.51.100.21");
        assertThat(resolver().resolve(request("10.0.0.2", "10.0.0.1"))).isEqualTo("10.0.0.1");
        var precise = new ClientAddressResolver(List.of("192.0.2.128/25", "2001:db8:1:0:8000::/65"));
        assertThat(precise.resolve(request("192.0.2.129", "198.51.100.21"))).isEqualTo("198.51.100.21");
        assertThat(precise.resolve(request("192.0.2.127", "198.51.100.21"))).isEqualTo("192.0.2.127");
        assertThat(precise.resolve(request("2001:db8:1:0:8000::1", "198.51.100.21"))).isEqualTo("198.51.100.21");
        assertThat(precise.resolve(request("2001:db8:1:0:7fff::1", "198.51.100.21"))).isEqualTo("2001:db8:1:0:7fff:0:0:1");
    }

    @Test
    void ipv6AndMappedIpv4HaveStableNumericIdentity() {
        var resolver = new ClientAddressResolver(List.of("2001:db8:1::/48", "10.0.0.0/8"));
        String client = resolver.resolve(request("2001:db8:1::2", "2001:DB8:2::1234, 2001:db8:1::1"));
        assertThat(client).isEqualTo("2001:db8:2:0:0:0:0:1234");
        assertThat(NetUtils.isMatchIpRule("2001:db8:2::1234", client)).isTrue();
        assertThat(NetUtils.isMatchIpRule("2001:db8:2::/48", client)).isTrue();
        assertThat(NetUtils.isMatchIpRule("2001:db8:3::/48", client)).isFalse();
        assertThat(resolver.resolve(request("::ffff:10.0.0.2", "::ffff:198.51.100.21")))
            .isEqualTo("198.51.100.21");
        assertThat(resolver.resolve(request("[2001:db8:1::2]", "2001:db8:2::1234"))).isEqualTo(client);
        assertThat(ServletUtils.getClientIP(request("[::1]", "192.0.2.77"))).isEqualTo("0:0:0:0:0:0:0:1");
        assertThat(NetUtils.isMatchIpRule("::ffff:198.51.100.21", "198.51.100.21")).isTrue();
        assertThat(NetUtils.isMatchIpRule("localhost/32", "127.0.0.1")).isFalse();
    }

    @Test
    void missingXffUsesPeerAndDoesNotFallBackToOtherHeaders() {
        var request = request("10.0.0.2", null);
        request.addHeader("X-Real-IP", "192.0.2.77");
        request.addHeader("Forwarded", "for=192.0.2.77");
        assertThat(resolver().resolve(request)).isEqualTo("10.0.0.2");
    }

    @Test
    void malformedTrustedChainsFailBeforeAnyBusinessHandler() throws Exception {
        for (String invalid : List.of("", "unknown", "127.1", "2130706433", "010.0.0.1", "256.0.0.1",
            "localhost", "198.51.100.21:443", "[2001:db8::1]", "fe80::1%eth0", "2001::db8::1",
            "192.0.2.77,", ",192.0.2.77", "192.0.2.77,,10.0.0.1")) {
            var request = request("10.0.0.2", invalid);
            var response = new MockHttpServletResponse();
            AtomicInteger calls = new AtomicInteger();
            new ClientAddressFilter(resolver()).doFilter(request, response,
                (req, res) -> calls.incrementAndGet());
            assertThat(response.getStatus()).as(invalid).isEqualTo(400);
            assertThat(calls).hasValue(0);
            assertThat(request.getAttribute(ServletUtils.CLIENT_IP_ATTRIBUTE)).isNull();
        }
    }

    @Test
    void boundsHeaderWorkAndAcceptsExactHopBudget() {
        String full = String.join(",", java.util.Collections.nCopies(32, "10.0.0.1"));
        assertThat(resolver().resolve(request("10.0.0.2", full))).isEqualTo("10.0.0.1");
        assertThatThrownBy(() -> resolver().resolve(request("10.0.0.2", full + ",10.0.0.1")))
            .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> resolver().resolve(request("10.0.0.2", " ".repeat(4097))))
            .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void invalidConfigurationIsRejectedRatherThanBroadeningTrust() {
        for (String invalid : List.of("", "10.0.0.1", "10.0.0.0/33", "::/129", "localhost/32",
            "0.0.0.0/-1", "10.0.0.0/8/", "10.0.0.0/+8", "*/0", "::ffff:10.0.0.0/128")) {
            assertThatThrownBy(() -> new ClientAddressResolver(List.of(invalid)))
                .as(invalid).isInstanceOf(IllegalArgumentException.class);
        }
        assertThat(new ClientAddressResolver(List.of("0.0.0.0/0"))
            .resolve(request("10.0.0.1", "198.51.100.21"))).isEqualTo("198.51.100.21");
    }

    @Test
    void canonicalResultSurvivesHeaderChangesAndNoRequestFailsClosed() throws Exception {
        var request = request("10.0.0.2", "198.51.100.21");
        new ClientAddressFilter(resolver()).doFilter(request, new MockHttpServletResponse(), (req, res) -> {
            request.removeHeader("X-Forwarded-For");
            request.addHeader("X-Forwarded-For", "192.0.2.77");
            assertThat(ServletUtils.getClientIP(request)).isEqualTo("198.51.100.21");
        });
        assertThat(ServletUtils.getClientIP((jakarta.servlet.http.HttpServletRequest) null)).isEmpty();
        assertThatThrownBy(() -> ServletUtils.getClientIP(request, "X-Custom-IP"))
            .isInstanceOf(IllegalArgumentException.class);
    }

    private ClientAddressResolver resolver() {
        return new ClientAddressResolver(List.of("10.0.0.0/8"));
    }

    private MockHttpServletRequest request(String peer, String xff) {
        var request = new MockHttpServletRequest("GET", "/test");
        request.setRemoteAddr(peer);
        if (xff != null) {
            request.addHeader("X-Forwarded-For", xff);
        }
        return request;
    }
}

package org.namewta.common.web.logging;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Tag;
import org.slf4j.LoggerFactory;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

import java.util.LinkedHashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

@Tag("dev")
class SysLogEventWriterTest {

    @Test
    void emitsOneParseableChineseJsonMessageAndPreservesBodyValue() {
        JsonMapper mapper = JsonMapper.builder().build();
        Logger logger = (Logger) LoggerFactory.getLogger(SysLogEventWriter.LOGGER_NAME);
        Level previousLevel = logger.getLevel();
        ListAppender<ILoggingEvent> appender = new ListAppender<>();
        appender.start();
        logger.setLevel(Level.INFO);
        logger.addAppender(appender);
        try {
            Map<String, Object> event = new LinkedHashMap<>();
            event.put("event", "HTTP_REQUEST");
            event.put("requestId", "request-id");
            event.put("bodyLogged", true);
            event.put("body", "line1\n\"quoted\"\u0001");

            new SysLogEventWriter(mapper).write(event);

            assertThat(appender.list).hasSize(1);
            String message = appender.list.getFirst().getFormattedMessage();
            assertThat(message).doesNotContain("\n");
            JsonNode parsed = mapper.readTree(message);
            assertThat(parsed.get("事件类型").asText()).isEqualTo("请求进入");
            assertThat(parsed.get("请求标识").asText()).isEqualTo("request-id");
            assertThat(parsed.get("正文已记录").asBoolean()).isTrue();
            assertThat(parsed.get("正文").asText()).isEqualTo("line1\n\"quoted\"\u0001");
            assertThat(parsed.has("event")).isFalse();
            assertThat(parsed.has("body")).isFalse();
        } finally {
            logger.detachAppender(appender);
            logger.setLevel(previousLevel);
            appender.stop();
        }
    }

    @Test
    void translatesResponseEventAndBodyOmissionReason() {
        JsonMapper mapper = JsonMapper.builder().build();
        Logger logger = (Logger) LoggerFactory.getLogger(SysLogEventWriter.LOGGER_NAME);
        Level previousLevel = logger.getLevel();
        ListAppender<ILoggingEvent> appender = new ListAppender<>();
        appender.start();
        logger.setLevel(Level.INFO);
        logger.addAppender(appender);
        try {
            Map<String, Object> event = new LinkedHashMap<>();
            event.put("event", "HTTP_RESPONSE");
            event.put("status", 200);
            event.put("bodyLogged", false);
            event.put("bodyOmissionReason", "NON_TEXT_CONTENT_TYPE");

            new SysLogEventWriter(mapper).write(event);

            JsonNode parsed = mapper.readTree(appender.list.getFirst().getFormattedMessage());
            assertThat(parsed.get("事件类型").asText()).isEqualTo("响应返回");
            assertThat(parsed.get("响应状态").asInt()).isEqualTo(200);
            assertThat(parsed.get("正文已记录").asBoolean()).isFalse();
            assertThat(parsed.get("正文省略原因").asText()).isEqualTo("非文本内容");
        } finally {
            logger.detachAppender(appender);
            logger.setLevel(previousLevel);
            appender.stop();
        }
    }
}

package org.namewta.common.web.logging;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.namewta.common.web.handler.GlobalExceptionHandler;
import org.slf4j.LoggerFactory;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

@Tag("dev")
class SysLogFailureRedactionTest {
    private static final String CANARY = "credential-canary-failure";

    @Test
    void sinkAndHandlerFailuresNeverPrintExceptionPayloadOrCause() throws Exception {
        Logger root = (Logger) LoggerFactory.getLogger(Logger.ROOT_LOGGER_NAME);
        ListAppender<ILoggingEvent> appender = new ListAppender<>();
        appender.start();
        root.addAppender(appender);
        try {
            MockHttpServletRequest request = new MockHttpServletRequest("POST", "/failed");
            MockHttpServletResponse response = new MockHttpServletResponse();
            new SysLogFilter(1024, event -> {
                throw new IllegalStateException(CANARY, new RuntimeException(CANARY));
            }).doFilter(request, response, (req, res) -> res.getWriter().write("unchanged"));
            new GlobalExceptionHandler().handleRuntimeException(new IllegalStateException(CANARY), request);
            assertThat(response.getContentAsString()).isEqualTo("unchanged");
            assertThat(appender.list).isNotEmpty();
            assertThat(appender.list).allSatisfy(event -> {
                assertThat(event.getFormattedMessage()).doesNotContain(CANARY);
                assertThat(event.getThrowableProxy()).isNull();
            });
        } finally {
            root.detachAppender(appender);
            appender.stop();
        }
    }

    @Test
    void formRepeatsRemainVisibleWhileNestedSecretsAndOAuthCodeDisappear() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        MockHttpServletRequest request = new MockHttpServletRequest("POST", "/context/sso/oauth2/token");
        request.setContextPath("/context");
        request.setContentType("application/x-www-form-urlencoded");
        request.addParameter("code", CANARY);
        request.addParameter("user[password]", CANARY);
        request.addParameter("page", "1", "2");
        new SysLogFilter(1024, events::add).doFilter(request, new MockHttpServletResponse(), (req, res) -> {
            assertThat(req.getParameter("code")).isEqualTo(CANARY);
            assertThat(req.getParameterValues("page")).containsExactly("1", "2");
        });
        assertThat(events.toString()).doesNotContain(CANARY);
        assertThat(((Map<?, ?>) events.getFirst().get("parameters")).get("page")).isEqualTo(List.of("1", "2"));
    }

    @Test
    void malformedJsonHasOnlySafeSummaryAndOriginalBytesReachApplication() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        byte[] original = ("{\"password\":\"" + CANARY).getBytes(StandardCharsets.UTF_8);
        MockHttpServletRequest request = new MockHttpServletRequest("POST", "/broken");
        request.setContentType("application/json");
        request.setContent(original);
        new SysLogFilter(1024, events::add).doFilter(request, new MockHttpServletResponse(), (req, res) ->
            assertThat(req.getInputStream().readAllBytes()).containsExactly(original));
        assertThat(events.getFirst()).containsEntry("body", "[REDACTED]");
    }

    @Test
    void utf8PrefixNeverContainsPartialCodePoint() {
        SysLogBody body = SysLogBody.logged("ééé".getBytes(StandardCharsets.UTF_8), 6, 5);
        assertThat(body.body()).isEqualTo("éé");
        assertThat(body.truncated()).isTrue();
    }
}

package org.namewta.common.web.logging;

import jakarta.servlet.AsyncContext;
import jakarta.servlet.AsyncEvent;
import jakarta.servlet.ServletException;
import org.namewta.common.web.filter.RepeatedlyRequestWrapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.slf4j.MDC;
import org.springframework.mock.web.MockAsyncContext;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicReference;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@Tag("dev")
class SysLogFilterTest {

    @AfterEach
    void clearMdc() {
        MDC.clear();
    }

    @Test
    void recordsCompleteRequestAndResponseWithServerRequestId() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024 * 1024, events::add);
        MockHttpServletRequest request = jsonRequest("{\"password\":\"plain\",\"token\":\"raw\"}");
        request.setQueryString("page=1&page=2");
        request.addParameter("page", "1", "2");
        request.addParameter("password", "plain-parameter");
        request.addHeader("Authorization", "Bearer raw-token");
        request.addHeader("Cookie", "session=raw-cookie");
        request.addHeader("X-Api-Key", "raw-api-key");
        request.addHeader("X-App-Key", "raw-app-key");
        request.addHeader("X-Signature", "raw-signature");
        request.addHeader(SysLogFilter.REQUEST_ID_HEADER, "client-request-id");
        MockHttpServletResponse response = new MockHttpServletResponse();

        filter.doFilter(request, response, (servletRequest, servletResponse) -> {
            assertThat(new String(servletRequest.getInputStream().readAllBytes(), StandardCharsets.UTF_8))
                .contains("plain", "raw");
            var httpResponse = (jakarta.servlet.http.HttpServletResponse) servletResponse;
            httpResponse.setStatus(201);
            httpResponse.setContentType("application/json");
            httpResponse.addHeader("Set-Cookie", "refresh=raw-cookie");
            httpResponse.getWriter().write("{\"code\":200,\"data\":{\"accessToken\":\"response-raw\"}}");
        });

        assertThat(events).hasSize(2);
        Map<String, Object> requestEvent = events.getFirst();
        Map<String, Object> responseEvent = events.getLast();
        String requestId = (String) requestEvent.get("requestId");
        assertThatCodeIsUuid(requestId);
        assertThat(requestId).isNotEqualTo("client-request-id");
        assertThat(response.getHeader(SysLogFilter.REQUEST_ID_HEADER)).isEqualTo(requestId);
        assertThat(responseEvent.get("requestId")).isEqualTo(requestId);
        assertThat(requestEvent)
            .containsEntry("event", "HTTP_REQUEST")
            .containsEntry("upstreamRequestId", "client-request-id")
            .containsEntry("bodyLogged", true)
            .containsEntry("body", "{\"password\":\"[REDACTED]\",\"token\":\"[REDACTED]\"}");
        assertThat(((Map<?, ?>) requestEvent.get("requestHeaders")).get("Authorization"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(((Map<?, ?>) requestEvent.get("requestHeaders")).get("Cookie"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(((Map<?, ?>) requestEvent.get("requestHeaders")).get("X-Api-Key"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(((Map<?, ?>) requestEvent.get("requestHeaders")).get("X-App-Key"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(((Map<?, ?>) requestEvent.get("requestHeaders")).get("X-Signature"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(((Map<?, ?>) requestEvent.get("parameters")).get("page"))
            .isEqualTo(List.of("1", "2"));
        assertThat(((Map<?, ?>) requestEvent.get("parameters")).get("password"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(responseEvent)
            .containsEntry("event", "HTTP_RESPONSE")
            .containsEntry("status", 201)
            .containsEntry("completed", true)
            .containsEntry("bodyLogged", true)
            .containsEntry("body", "{\"code\":200,\"data\":{\"accessToken\":\"[REDACTED]\"}}");
        assertThat(((Map<?, ?>) responseEvent.get("responseHeaders")).get("Set-Cookie"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(response.getContentAsString())
            .isEqualTo("{\"code\":200,\"data\":{\"accessToken\":\"response-raw\"}}");
        assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID)).isNull();
    }

    @Test
    void concealsTruncatedJsonInsteadOfFallingBackToSensitivePlaintext() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(20, events::add);
        MockHttpServletRequest request = jsonRequest("{\"password\":\"plain\",\"visible\":true}");

        filter.doFilter(request, new MockHttpServletResponse(), (servletRequest, servletResponse) ->
            assertThat(new String(servletRequest.getInputStream().readAllBytes(), StandardCharsets.UTF_8))
                .contains("plain", "visible"));

        assertThat(events.getFirst())
            .containsEntry("bodyLogged", true)
            .containsEntry("body", "[REDACTED]")
            .containsEntry("truncated", true);
    }

    @Test
    void recursivelyRedactsOpenApiCredentialMaterial() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024, events::add);
        MockHttpServletRequest request = jsonRequest("""
            {"appSecret":"secret-value","nested":{"signature":"signature-value",\
            "machine_token":"machine-token-value","safe":"visible"}}""");

        filter.doFilter(request, new MockHttpServletResponse(), (servletRequest, servletResponse) -> {
        });

        assertThat(events.getFirst().get("body")).isEqualTo(
            "{\"appSecret\":\"[REDACTED]\",\"nested\":{\"signature\":\"[REDACTED]\","
                + "\"machine_token\":\"[REDACTED]\",\"safe\":\"visible\"}}");
        assertThat(events.getFirst().toString())
            .doesNotContain("secret-value", "signature-value", "machine-token-value");
    }

    @Test
    void hidesUnstructuredTextWithoutChangingUtf8BusinessBody() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(5, events::add);
        MockHttpServletRequest request = new MockHttpServletRequest("POST", "/unicode");
        request.setContentType("text/plain");
        request.setContent("ééé".getBytes(StandardCharsets.UTF_8));
        MockHttpServletResponse response = new MockHttpServletResponse();

        filter.doFilter(request, response, (servletRequest, servletResponse) -> {
            assertThat(new String(servletRequest.getInputStream().readAllBytes(), StandardCharsets.UTF_8))
                .isEqualTo("ééé");
            var httpResponse = (jakarta.servlet.http.HttpServletResponse) servletResponse;
            httpResponse.setContentType("text/plain");
            httpResponse.getOutputStream().write("ééé".getBytes(StandardCharsets.UTF_8));
        });

        assertThat(events).hasSize(2);
        assertThat(events.getFirst())
            .containsEntry("body", "[REDACTED]")
            .containsEntry("bodyLength", 6L)
            .containsEntry("truncated", true);
        assertThat(events.getLast())
            .containsEntry("body", "[REDACTED]")
            .containsEntry("bodyLength", 6L)
            .containsEntry("truncated", true);
        assertThat(response.getContentAsString()).isEqualTo("ééé");
    }

    @Test
    void omitsBinaryResponseBodyButKeepsMetadata() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024, events::add);
        MockHttpServletRequest request = new MockHttpServletRequest("GET", "/download");
        MockHttpServletResponse response = new MockHttpServletResponse();
        byte[] bytes = {0, 1, 2, 3};

        filter.doFilter(request, response, (servletRequest, servletResponse) -> {
            var httpResponse = (jakarta.servlet.http.HttpServletResponse) servletResponse;
            httpResponse.setContentType("application/octet-stream");
            httpResponse.setContentLength(bytes.length);
            httpResponse.getOutputStream().write(bytes);
        });

        assertThat(events.getLast())
            .containsEntry("bodyLogged", false)
            .containsEntry("bodyLength", 4L)
            .containsEntry("bodyOmissionReason", "NON_TEXT_CONTENT_TYPE")
            .containsEntry("contentLength", 4L);
        assertThat(response.getContentAsByteArray()).containsExactly(bytes);
    }

    @Test
    void preservesUnhandledExceptionAndMarksResponseIncomplete() {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024, events::add);
        MockHttpServletRequest request = new MockHttpServletRequest("GET", "/failure");
        MockHttpServletResponse response = new MockHttpServletResponse();
        IllegalStateException cause = new IllegalStateException("root");
        ServletException failure = new ServletException("failed", cause);

        assertThatThrownBy(() -> filter.doFilter(request, response, (ignoredRequest, ignoredResponse) -> {
            throw failure;
        })).isSameAs(failure).hasCause(cause);

        assertThat(events).hasSize(2);
        assertThat(events.getLast()).containsEntry("completed", false);
        assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID)).isNull();
    }

    @Test
    void completesAsyncResponseExactlyOnce() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024, events::add);
        MockHttpServletRequest request = new MockHttpServletRequest("GET", "/async");
        request.setAsyncSupported(true);
        MockHttpServletResponse response = new MockHttpServletResponse();
        AtomicReference<AsyncContext> async = new AtomicReference<>();

        filter.doFilter(request, response, (servletRequest, servletResponse) ->
            async.set(servletRequest.startAsync(servletRequest, servletResponse)));

        assertThat(events).hasSize(1);
        var asyncResponse = (jakarta.servlet.http.HttpServletResponse) async.get().getResponse();
        asyncResponse.setContentType("application/json");
        asyncResponse.getWriter().write("{\"done\":true}");
        async.get().complete();

        assertThat(events).hasSize(2);
        assertThat(events.getLast())
            .containsEntry("completed", true)
            .containsEntry("body", "{\"done\":true}");
        assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID)).isNull();
    }

    @Test
    void recordsAsyncTimeoutOnceAndRestoresCallbackMdc() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        List<String> eventRequestIds = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024, event -> {
            events.add(event);
            eventRequestIds.add(MDC.get(SysLogFilter.MDC_REQUEST_ID));
        });
        MockHttpServletRequest request = new MockHttpServletRequest("GET", "/async-timeout");
        request.setAsyncSupported(true);
        MockHttpServletResponse response = new MockHttpServletResponse();
        AtomicReference<AsyncContext> async = new AtomicReference<>();

        filter.doFilter(request, response, (servletRequest, servletResponse) ->
            async.set(servletRequest.startAsync(servletRequest, servletResponse)));

        MockAsyncContext context = (MockAsyncContext) async.get();
        var listener = context.getListeners().getFirst();
        listener.onTimeout(new AsyncEvent(context, context.getRequest(), context.getResponse()));
        listener.onComplete(new AsyncEvent(context, context.getRequest(), context.getResponse()));

        assertThat(events).hasSize(2);
        assertThat(events.getLast()).containsEntry("completed", false);
        assertThat(eventRequestIds).containsOnly((String) events.getFirst().get("requestId"));
        assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID)).isNull();
    }

    @Test
    void excludesMultipartRequestAndSseResponseBodies() throws Exception {
        List<Map<String, Object>> events = new ArrayList<>();
        SysLogFilter filter = new SysLogFilter(1024, events::add);
        MockHttpServletRequest request = new MockHttpServletRequest("POST", "/stream");
        request.setContentType("multipart/form-data; boundary=test");
        request.setContent("raw-file-content".getBytes(StandardCharsets.UTF_8));
        request.addParameter("description", "original-name");
        MockHttpServletResponse response = new MockHttpServletResponse();

        filter.doFilter(request, response, (servletRequest, servletResponse) -> {
            var httpResponse = (jakarta.servlet.http.HttpServletResponse) servletResponse;
            httpResponse.setContentType("text/event-stream");
            httpResponse.getOutputStream().write("data: raw-event\n\n".getBytes(StandardCharsets.UTF_8));
        });

        assertThat(events.getFirst())
            .containsEntry("bodyLogged", false)
            .containsEntry("bodyOmissionReason", "MULTIPART");
        assertThat(((Map<?, ?>) events.getFirst().get("parameters")).get("description"))
            .isEqualTo(List.of("original-name"));
        assertThat(events.getLast())
            .containsEntry("bodyLogged", false)
            .containsEntry("bodyLength", 17L)
            .containsEntry("bodyOmissionReason", "STREAMING");
        assertThat(response.getContentAsString()).isEqualTo("data: raw-event\n\n");
    }

    @Test
    void preservesPlainJsonThroughNestedWrappersAndRedactsAuditCopies() throws Exception {
        String requestBody = "{\"password\":\"request-secret-canary\",\"displayName\":\"测试\"}";
        String responseBody = "{\"token\":\"response-secret-canary\",\"code\":200}";
        MockHttpServletRequest request = jsonRequest(requestBody);
        request.addHeader("Authorization", "Bearer header-secret-canary");
        MockHttpServletResponse response = new MockHttpServletResponse();
        var repeatableRequest = new RepeatedlyRequestWrapper(request, response);
        var nestedRequest = new jakarta.servlet.http.HttpServletRequestWrapper(repeatableRequest);
        var nestedResponse = new jakarta.servlet.http.HttpServletResponseWrapper(response);
        List<Map<String, Object>> events = new ArrayList<>();

        new SysLogFilter(1024, events::add).doFilter(nestedRequest, nestedResponse,
            (servletRequest, servletResponse) -> {
                assertThat(new String(servletRequest.getInputStream().readAllBytes(), StandardCharsets.UTF_8))
                    .isEqualTo(requestBody);
                assertThat(new String(servletRequest.getInputStream().readAllBytes(), StandardCharsets.UTF_8))
                    .isEqualTo(requestBody);
                var httpResponse = (jakarta.servlet.http.HttpServletResponse) servletResponse;
                httpResponse.setContentType("application/json");
                httpResponse.getWriter().write(responseBody);
        });

        assertThat(events).hasSize(2);
        assertThat(events.getFirst()).containsEntry("body",
            "{\"password\":\"[REDACTED]\",\"displayName\":\"测试\"}");
        assertThat(events.getLast()).containsEntry("body", "{\"token\":\"[REDACTED]\",\"code\":200}");
        assertThat(events.toString()).doesNotContain("request-secret-canary", "response-secret-canary",
            "header-secret-canary");
        assertThat(((Map<?, ?>) events.getFirst().get("requestHeaders")).get("Authorization"))
            .isEqualTo(List.of("[REDACTED]"));
        assertThat(response.getContentAsString()).isEqualTo(responseBody);
        assertThat(response.getHeader("encrypt-key")).isNull();
    }

    @Test
    void restoresPreexistingMdcValue() throws Exception {
        MDC.put(SysLogFilter.MDC_REQUEST_ID, "outer-request-id");
        SysLogFilter filter = new SysLogFilter(1024, ignored -> {
        });

        filter.doFilter(new MockHttpServletRequest("GET", "/mdc"), new MockHttpServletResponse(),
            (request, response) -> assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID))
                .isNotEqualTo("outer-request-id"));

        assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID)).isEqualTo("outer-request-id");
    }

    @Test
    void loggingFailureDoesNotChangeBusinessResponse() throws Exception {
        SysLogFilter filter = new SysLogFilter(1024, event -> {
            throw new IllegalStateException("encoder unavailable");
        });
        MockHttpServletRequest request = jsonRequest("{\"value\":1}");
        MockHttpServletResponse response = new MockHttpServletResponse();

        filter.doFilter(request, response, (servletRequest, servletResponse) -> {
            var httpResponse = (jakarta.servlet.http.HttpServletResponse) servletResponse;
            httpResponse.setStatus(202);
            httpResponse.setContentType("application/json");
            httpResponse.getWriter().write("{\"ok\":true}");
        });

        assertThat(response.getStatus()).isEqualTo(202);
        assertThat(response.getContentAsString()).isEqualTo("{\"ok\":true}");
        assertThat(response.getHeader(SysLogFilter.REQUEST_ID_HEADER)).isNotBlank();
        assertThat(MDC.get(SysLogFilter.MDC_REQUEST_ID)).isNull();
    }

    @Test
    void neverCopiesRawOAuthQueryAndRedirectIntoLogEvents() throws Exception {
        String canary = "credential-canary-query";
        List<Map<String, Object>> events = new ArrayList<>();
        MockHttpServletRequest request = new MockHttpServletRequest("GET", "/sso/oauth2/authorize");
        request.setQueryString("code=" + canary + "&page=1&page=2");
        request.addParameter("code", canary);
        request.addParameter("page", "1", "2");
        request.addHeader("Referer", "https://test.invalid/callback?code=" + canary);
        MockHttpServletResponse response = new MockHttpServletResponse();

        new SysLogFilter(1024, events::add).doFilter(request, response, (req, res) -> {
            var httpResponse = (jakarta.servlet.http.HttpServletResponse) res;
            httpResponse.setContentType("application/json");
            httpResponse.setHeader("Location", "https://test.invalid/callback?code=" + canary);
            httpResponse.getWriter().write("{\"redirectUri\":\"https://test.invalid/callback?code=" + canary + "\"}");
        });

        assertThat(events.toString()).doesNotContain(canary);
        assertThat(((Map<?, ?>) events.getFirst().get("parameters")).get("page"))
            .isEqualTo(List.of("1", "2"));
        assertThat(response.getContentAsString()).contains(canary);
    }

    private MockHttpServletRequest jsonRequest(String body) {
        MockHttpServletRequest request = new MockHttpServletRequest("POST", "/api/test");
        request.setContentType("application/json");
        request.setContent(body.getBytes(StandardCharsets.UTF_8));
        return request;
    }

    private void assertThatCodeIsUuid(String value) {
        assertThat(value).isEqualTo(UUID.fromString(value).toString());
    }
}
